pub(super) fn analysis__fixture_quality__is_weak_negative(mut finding: Value) -> Result<Value> {
    let mut expected: Value;
    let mut metrics: Value;
    let mut rationale: Value;
    metrics = indexed(&finding, &json!("quality_metrics"))?;
    expected = indexed(&finding, &json!("expected"))?;
    rationale = unary_method(
        &indexed(&finding, &json!("rationale"))?,
        "lower",
        &Value::Null,
    )?;
    if (contains(
        &unique(vec![json!("hold"), json!("blocked")]),
        &get(&expected, &json!("status"), Value::Null),
    )) || (contains(
        &unique(vec![json!("hold"), json!("blocked")]),
        &get(&expected, &json!("readiness_effect"), Value::Null),
    )) {
        return Ok(json!(false));
    }
    if (equal(
        &get(&metrics, &json!("asserts_finding_code"), Value::Null),
        &json!(true),
    )) || (equal(
        &get(&metrics, &json!("negative_oracle"), Value::Null),
        &json!(true),
    )) {
        return Ok(json!(false));
    }
    return Ok({
        let first = json!(contains(&rationale, &json!("negative")));
        if !truth(&first) {
            first
        } else {
            {
                let first = json!(!contains(&rationale, &json!("finding")));
                if !truth(&first) {
                    first
                } else {
                    json!(!contains(&rationale, &json!("hold")))
                }
            }
        }
    });
}

